package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class ColorStateListDrawable extends ColorDrawable { public ColorStateListDrawable(){super();} public ColorStateListDrawable(ColorStateList c){super(c.getDefaultColor());} public ColorStateList getColorStateList(){return ColorStateList.valueOf(getColor());} public void setColorStateList(ColorStateList c){setColor(c.getDefaultColor());} }